class Solution { public int maxValueAfterReverse(int[] nums){int n=nums.length,base=0,gain=0,maxOfMin=Integer.MIN_VALUE,minOfMax=Integer.MAX_VALUE;for(int i=0;i<n-1;i++){int a=nums[i],b=nums[i+1],difference=Math.abs(a-b);base+=difference;gain=Math.max(gain,Math.abs(nums[0]-b)-difference);gain=Math.max(gain,Math.abs(nums[n-1]-a)-difference);maxOfMin=Math.max(maxOfMin,Math.min(a,b));minOfMax=Math.min(minOfMax,Math.max(a,b));}if(n>1)gain=Math.max(gain,2*(maxOfMin-minOfMax));return base+gain;} }
